function quizPage(){let idx=state.qIndex, q=MCQS[idx];$('#practiceContent').innerHTML=`<div class="panel"><div class="question-counter">MULTIPLE CHOICE · QUESTION ${idx+1} / ${MCQS.length} · ${q[4].toUpperCase()}</div><div class="progress-track" style="margin:13px 0 23px"><div class="progress-fill" style="width:${(idx+1)/MCQS.length*100}%"></div></div><h2>${q[0]}</h2><div id="mcChoices">${q[1].map((opt,i)=>`<button class="match-item" data-option="${i}"><b>${'ABCD'[i]}.</b> ${esc(opt)}</button>`).join('')}</div><div id="mcFeedback" aria-live="polite"></div><div class="action-row"><button class="btn" id="mcPrev" ${idx===0?'disabled':''}>← Previous</button><button class="btn primary" id="mcNext">${idx===MCQS.length-1?'Restart quiz':'Next question →'}</button><button class="btn small" id="mcRandom">Shuffle question ↝</button></div><div class="divider"></div><p class="text-muted">Unique correct answers recorded: <b>${Object.keys(state.qRight).length} / ${MCQS.length}</b>. Wrong answers tracked for review. Repeat questions to consolidate your understanding.</p><button class="btn small" id="mcReview">Review errors (${Object.keys(state.qWrong).length})</button></div>`;
 $$('[data-option]').forEach(b=>b.onclick=()=>{let answer=+b.dataset.option,right=answer===q[2];$$('[data-option]').forEach(z=>{z.disabled=true;z.classList.toggle('correct',+z.dataset.option===q[2]);z.classList.toggle('wrong',+z.dataset.option===answer&&!right)});$('#mcFeedback').innerHTML=`<div class="feedback ${right?'':'bad'}"><b>${right?'Correct!':'Not quite — answer '+('ABCD'[q[2]])+'.'}</b> ${q[3]}</div>`;if(right){state.qRight[idx]=true;delete state.qWrong[idx]}else{state.qWrong[idx]=true;state.mistakes['mc'+idx]=true}persist();updateHeader()});
 $('#mcPrev').onclick=()=>{state.qIndex=Math.max(0,idx-1);quizPage()};$('#mcNext').onclick=()=>{state.qIndex=idx===MCQS.length-1?0:idx+1;quizPage()};$('#mcRandom').onclick=()=>{state.qIndex=Math.floor(Math.random()*MCQS.length);quizPage()};$('#mcReview').onclick=()=>{let errs=Object.keys(state.qWrong).map(Number);if(!errs.length){toast('No missed questions yet — great work!');return}state.qIndex=errs[0];quizPage()}}
function blanksPage(){let i=state.blankIndex,q=BLANKS[i],parts=q[0].split('____');$('#practiceContent').innerHTML=`<div class="panel blanks"><div class="question-counter">FILL THE MISSING WORD · ${i+1} / ${BLANKS.length} · ${q[3].toUpperCase()}</div><h2>Complete the statement</h2><p>${esc(parts[0])}<input id="blankInput" autocomplete="off" placeholder="Type missing word" aria-label="Missing word" />${esc(parts[1]||'')}</p><div id="blankResult" aria-live="polite"></div><div class="action-row"><button class="btn primary" id="blankCheck">Check answer</button><button class="btn" id="blankHint">Hint</button><button class="btn" id="blankReveal">Reveal</button></div><div class="divider"></div><div class="action-row"><button class="btn" id="blankPrev" ${i===0?'disabled':''}>← Previous</button><button class="btn primary" id="blankNext">${i===BLANKS.length-1?'Back to start':'Next →'}</button></div><p class="text-muted">Correct blanks completed: ${Object.keys(state.blanksRight).length} / ${BLANKS.length}</p></div>`;
 const check=()=>{let entered=$('#blankInput').value.trim().toLowerCase().replace(/[\s_-]+/g,' ');let good=entered===q[1].toLowerCase();if(good){state.blanksRight[i]=true;persist();updateHeader()}$('#blankResult').innerHTML=`<div class="feedback ${good?'':'bad'}"><b>${good?'✓ Correct!':'Try again.'}</b> ${good?q[2]:'Think about the process or component being defined.'}</div>`};$('#blankCheck').onclick=check;$('#blankInput').onkeydown=e=>{if(e.key==='Enter')check()};$('#blankHint').onclick=()=>$('#blankResult').innerHTML=`<div class="feedback">Hint: ${q[2]} Starts with <b>${q[1][0].toUpperCase()}</b>.</div>`;$('#blankReveal').onclick=()=>{$('#blankInput').value=q[1];$('#blankResult').innerHTML=`<div class="feedback">Answer: <b>${q[1]}</b>. ${q[2]}</div>`};$('#blankPrev').onclick=()=>{state.blankIndex=Math.max(0,i-1);blanksPage()};$('#blankNext').onclick=()=>{state.blankIndex=(i+1)%BLANKS.length;blanksPage()}}
function matchPage(){let done=Object.keys(state.matchDone).length;$('#practiceContent').innerHTML=`<div class="panel"><div class="eyebrow">MATCHING GAME</div><h2>Match terms to meanings</h2><p>Select a term on the left and its matching explanation on the right. Works on mobile and desktop; no dragging required.</p><div class="data-grid"><div class="data-cell"><small>PAIRS MATCHED</small><strong id="matchScore">${done} / ${MATCH.length}</strong></div><div class="data-cell"><small>YOUR SELECTED TERM</small><strong id="matchSelected" style="font-size:15px">${state.matchLeft===null?'None':esc(MATCH[state.matchLeft][0])}</strong></div><div class="data-cell"><small>GAME STATE</small><strong style="font-size:16px">${done===MATCH.length?'Completed!':'In progress'}</strong></div></div><div class="match-columns"><div><h3>Terms</h3>${MATCH.map((pair,i)=>`<button data-term="${i}" class="match-item ${state.matchDone[i]?'done':''} ${state.matchLeft===i?'selected':''}" ${state.matchDone[i]?'disabled':''}>${esc(pair[0])}${state.matchDone[i]?' ✓':''}</button>`).join('')}</div><div><h3>Descriptions</h3>${state.matchOrder.map(i=>`<button data-def="${i}" class="match-item ${state.matchDone[i]?'done':''}" ${state.matchDone[i]?'disabled':''}>${esc(MATCH[i][1])}</button>`).join('')}</div></div><div class="action-row"><button class="btn" id="matchReset">↻ Restart matching</button></div></div>`;
 $$('[data-term]').forEach(b=>b.onclick=()=>{state.matchLeft=+b.dataset.term;$$('[data-term]').forEach(x=>x.classList.toggle('selected',+x.dataset.term===state.matchLeft));$('#matchSelected').textContent=MATCH[state.matchLeft][0]});$$('[data-def]').forEach(b=>b.onclick=()=>{if(state.matchLeft===null){toast('Select a term on the left first');return}if(state.matchLeft===+b.dataset.def){state.matchDone[state.matchLeft]=true;toast('✓ Correct match!');state.matchLeft=null;matchPage();if(Object.keys(state.matchDone).length===MATCH.length)toast('🎉 All pairs matched!')}else{toast('Not a match. Check the definitions and try again.');b.classList.add('wrong')}});$('#matchReset').onclick=()=>{state.matchDone={};state.matchLeft=null;matchPage()}}
