function hotspotPage(){if(state.hotIndex===undefined)state.hotIndex=0;let target=HOTTARGETS[state.hotIndex%HOTTARGETS.length];$('#practiceContent').innerHTML=`<div class="panel"><div class="eyebrow">VISUAL RECALL · HOTSPOT ${state.hotIndex+1} / ${HOTTARGETS.length}</div><h2>Tap the ${target}</h2><p>Locate the target on the 3D-inspired plasma membrane schematic. Tap a structure directly or use a labelled button below for accessibility.</p><div class="sim-stage">${bilayerSvg()}</div><div id="hotResult" aria-live="polite"></div><div class="topic-meta">${Object.keys(COMPONENTS).map(n=>`<button class="btn small" data-hot="${n}">${n}</button>`).join('')}</div><div class="action-row"><button class="btn primary" id="hotNext">Next target →</button><button class="btn" id="hotRestart">Restart</button></div></div>`;
 function attempt(n){let right=n===target;$('#hotResult').innerHTML=`<div class="feedback ${right?'':'bad'}"><b>${right?'✓ Correct!':'Not quite.'}</b> ${COMPONENTS[n]}</div>`;if(right)toast('Great identification!')}$$('[data-hot]').forEach(b=>b.onclick=()=>attempt(b.dataset.hot));state.hotAttempt=attempt;$('#hotNext').onclick=()=>{state.hotIndex=(state.hotIndex+1)%HOTTARGETS.length;hotspotPage()};$('#hotRestart').onclick=()=>{state.hotIndex=0;hotspotPage()}}
