const ORDER_STEPS=['The specific ion binds to the protein pump.','ATP is hydrolysed, providing energy.','Carrier changes conformation.','Ion is transported and released on the other side.','Carrier returns to its original shape.'];
function sequencePage(){let order=state.sequence;$('#practiceContent').innerHTML=`<div class="panel"><div class="eyebrow">SEQUENCING CHALLENGE</div><h2>Order the stages of active transport</h2><p>Use the up/down controls to put the steps into a logical order, then check your sequence.</p>${order.map((n,i)=>`<div class="order-row"><span><b>${i+1}.</b> ${ORDER_STEPS[n]}</span><button class="btn small" data-move="${i},-1" ${i===0?'disabled':''} aria-label="Move step up">↑</button><button class="btn small" data-move="${i},1" ${i===order.length-1?'disabled':''} aria-label="Move step down">↓</button></div>`).join('')}<div id="seqFeedback" aria-live="polite"></div><div class="action-row"><button class="btn primary" id="seqCheck">Check sequence</button><button class="btn" id="seqReset">Shuffle again</button></div></div>`;$$('[data-move]').forEach(b=>b.onclick=()=>{let [i,step]=b.dataset.move.split(',').map(Number),j=i+step;[order[i],order[j]]=[order[j],order[i]];sequencePage()});$('#seqCheck').onclick=()=>{let correct=order.every((n,i)=>i===n);$('#seqFeedback').innerHTML=`<div class="feedback ${correct?'':'bad'}">${correct?'✓ Well ordered!':'Some steps are not in the right order. Use the step-by-step mechanism in Section 5.4 as a guide.'}</div>`};$('#seqReset').onclick=()=>{state.sequence=[2,0,4,1,3].sort(()=>Math.random()-.5);sequencePage()}}
function flashPage(){let i=state.flashIndex,card=FLASH[i];$('#practiceContent').innerHTML=`<div class="panel"><div class="eyebrow">FLASHCARDS · ${i+1} / ${FLASH.length}</div><p class="text-muted">Tap the card to reveal the answer. Decide whether you know it or need to repeat it.</p><div class="flash" id="flashCard" tabindex="0" role="button" aria-label="Flip flashcard"><span>${state.flip?'ANSWER':'QUESTION'}</span><h3>${state.flip?esc(card[1]):esc(card[0])}</h3><span>Tap to ${state.flip?'show question':'reveal answer'}</span></div><div class="action-row"><button class="btn" id="flashPrev" ${i===0?'disabled':''}>← Previous</button><button class="btn purple" id="flashFlip">Flip card</button><button class="btn" id="flashAgain">Again ↻</button><button class="btn primary" id="flashKnow">✓ I know this</button><button class="btn" id="flashNext">Next →</button></div><div class="note"><b>Mastered cards:</b> ${Object.keys(state.flashKnown).length} / ${FLASH.length}. Marking “again” removes a known mark so you can revisit difficult facts.</div></div>`;function flip(){state.flip=!state.flip;flashPage()}$('#flashCard').onclick=flip;$('#flashCard').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();flip()}};$('#flashFlip').onclick=flip;function go(delta){state.flashIndex=(i+delta+FLASH.length)%FLASH.length;state.flip=false;flashPage()}$('#flashPrev').onclick=()=>go(-1);$('#flashNext').onclick=()=>go(1);$('#flashAgain').onclick=()=>{delete state.flashKnown[i];persist();go(1)};$('#flashKnow').onclick=()=>{state.flashKnown[i]=true;persist();go(1)}}
function exam(){let list=EXAMS.map((q,i)=>({...q,orig:i})).filter(q=>state.examFilter==='all'||q.topic===state.examFilter);if(state.examIndex>=list.length)state.examIndex=0;let q=list[state.examIndex];app.innerHTML=head('ASSESSMENT STUDIO','Exam questions & mark schemes','Practise original OCR-style structured questions, self-mark against discrete assessment points, and then try authentic papers from the OCR archive.')+`<div class="panel"><div class="split"><div class="control"><label>Filter by topic</label><select id="examFilter" class="glossary-search" style="margin:0;padding:9px"><option value="all">All topics (${EXAMS.length})</option>${LESSONS.map(l=>`<option value="${l.id}" ${state.examFilter===l.id?'selected':''}>${l.number} ${l.title}</option>`).join('')}</select></div><div class="control"><label>Exam timer</label><div class="action-row" style="margin:0"><span class="pill" id="clockLabel" style="font-size:15px">${clockText()}</span><button id="clockToggle" class="btn small">${state.examTiming?'Pause':'Start'}</button><button id="clockReset" class="btn small">Reset</button></div></div></div><div class="divider"></div><div class="question-counter">QUESTION ${state.examIndex+1} / ${list.length} · ${q.diff.toUpperCase()} · <b>${q.marks} MARKS</b> · ${q.topic.toUpperCase()}</div><h2>${esc(q.q)}</h2><p>Write your answer in complete scientific statements. Include structure–function links and precise vocabulary.</p><textarea id="examText" class="answerbox" placeholder="Write your answer here…" aria-label="Exam response">${esc(state.examAnswers[q.orig]||'')}</textarea><div class="action-row"><button class="btn primary" id="showScheme">${state.showMarks?'Hide mark scheme':'Reveal mark scheme'}</button><button class="btn" id="examPrev" ${state.examIndex===0?'disabled':''}>← Previous</button><button class="btn" id="examNext">Next →</button><span class="pill green">${state.examScores[q.orig]??'Not marked'} / ${q.marks} self-awarded</span></div><div id="scheme" style="display:${state.showMarks?'block':'none'}"><div class="note purple"><b>Examiner tip:</b> ${q.tip}</div><h3>Self-marking checklist · 1 mark per point</h3><p class="text-muted">Award each mark only if your response clearly contains that point. This is guided self-assessment, not AI grading.</p>${q.points.map((pt,i)=>`<label class="inline-check" style="padding:9px;border-bottom:1px solid #e6edf2"><input type="checkbox" data-tick="${i}" ${state.examTicks[i]?'checked':''}/> ${pt} <small class="text-muted">[1]</small></label>`).join('')}<div class="action-row"><button id="saveMarks" class="btn primary">Save my mark</button><span class="pill" id="markCount">${Object.values(state.examTicks).filter(Boolean).length} / ${q.marks}</span></div></div><div class="divider"></div><h3>Real OCR past papers</h3><p><a class="btn small" href="#practice" onclick="state.practiceTab='bankmcq'">30 original OCR-style MCQs →</a> <a class="btn small" href="#practice" onclick="state.practiceTab='bankmsq'">30 original OCR-style MSQs →</a></p><p>The practice question above is <b>original, not a verbatim past-paper question</b>. For genuine OCR question papers and official mark schemes, follow the links below.</p><div class="action-row"><a class="btn primary" href="https://pmt.physicsandmathstutor.com/download/Biology/A-level/Topic-Qs/OCR-A/2-Foundations-in-Biology/Set-D/2.5%20Biological%20Membranes%20QP.pdf" target="_blank" rel="noopener noreferrer">Biological Membranes · question PDF ↗</a><a class="btn" href="https://pmt.physicsandmathstutor.com/download/Biology/A-level/Topic-Qs/OCR-A/2-Foundations-in-Biology/Set-D/2.5%20Biological%20Membranes%20MS.pdf" target="_blank" rel="noopener noreferrer">Matching mark scheme PDF ↗</a><a class="btn" href="#pastpapers">All direct topic links →</a></div></div>`;
 $('#examFilter').onchange=e=>{state.examFilter=e.target.value;state.examIndex=0;state.showMarks=false;state.examTicks={};exam()};$('#examText').oninput=e=>{state.examAnswers[q.orig]=e.target.value;persist()};$('#showScheme').onclick=()=>{state.showMarks=!state.showMarks;$('#showScheme').textContent=state.showMarks?'Hide mark scheme':'Reveal mark scheme';$('#scheme').style.display=state.showMarks?'block':'none'};function move(d){state.examIndex=(state.examIndex+d+list.length)%list.length;state.showMarks=false;state.examTicks={};exam()}$('#examPrev').onclick=()=>move(-1);$('#examNext').onclick=()=>move(1);
 $$('[data-tick]').forEach(b=>b.onchange=e=>{state.examTicks[e.target.dataset.tick]=e.target.checked;$('#markCount').textContent=Object.values(state.examTicks).filter(Boolean).length+' / '+q.marks});$('#saveMarks')?.addEventListener('click',()=>{state.examScores[q.orig]=Object.values(state.examTicks).filter(Boolean).length;persist();toast('Self-assessment saved');exam()});$('#clockToggle').onclick=()=>{state.examTiming=!state.examTiming;$('#clockToggle').textContent=state.examTiming?'Pause':'Start'};$('#clockReset').onclick=()=>{state.sec=0;state.examTiming=false;$('#clockLabel').textContent='00:00';$('#clockToggle').textContent='Start'}
}
function clockText(){return String(Math.floor(state.sec/60)).padStart(2,'0')+':'+String(state.sec%60).padStart(2,'0')}
setInterval(()=>{if(state.examTiming){state.sec++;const e=$('#clockLabel');if(e)e.textContent=clockText()}},1000);
const EXAMPLE_PIC='https://openstax.org/apps/image-cdn/v1/f%3Dwebp/apps/archive/20260209.222123/resources/0e15992c8bbd25e60d465b32e0c88ac77365ac2e';
function resources(){app.innerHTML=head('REFERENCE & LAB WORK','Resources, past papers & practicals','Use trusted public learning resources, examine the 3D infographic gallery, and process your own osmosis experiment data.')+`<div class="tabbar">${[['papers','Past papers'],['gallery','Image gallery'],['practicals','Practical data lab'],['glossary','Biology glossary']].map(([k,n])=>`<button data-restab="${k}" class="${state.resourceTab===k?'active':''}">${n}</button>`).join('')}</div><div id="resourceContent"></div>`;$$('[data-restab]').forEach(b=>b.onclick=()=>{state.resourceTab=b.dataset.restab;resources()});resourcesRender()}
function resourcesRender(){({papers:papersPage,gallery:galleryPage,practicals:practicalsPage,glossary:glossaryPage})[state.resourceTab]()}
