function galleryPage(){const gallery=[['Fluid mosaic structure','assets/structure.png'],['Temperature & solvents','assets/temperature.png'],['Diffusion','assets/diffusion.png'],['Active transport','assets/active.png'],['Osmosis','assets/osmosis.png']];$('#resourceContent').innerHTML=`<div class="panel"><h2>Explore the diagrams</h2><p>Original light cinematic 3D infographic images, one per topic. Select any image to enlarge for revision.</p><div class="gallery">${gallery.map(([name,path])=>`<figure><img class="reference-image" loading="lazy" src="${path}" alt="3D educational infographic: ${name}" data-lightbox="${path}"><figcaption>${name}</figcaption></figure>`).join('')}</div></div><div class="panel" style="margin-top:18px"><h2>Online reference image · OpenStax</h2><p>External membrane illustration from <a href="https://openstax.org/books/biology-ap-courses/pages/5-1-components-and-structure" target="_blank" rel="noopener">OpenStax Biology for AP® Courses, Section 5.1</a> (Julianne Zedalis & John Eggebrecht). This remotely loaded image requires an internet connection.</p><img class="reference-image" id="openstaxImage" alt="OpenStax fluid mosaic model diagram" src="${EXAMPLE_PIC}" onerror="this.src='assets/structure.png';this.alt='Original fluid mosaic backup illustration'"/><div class="action-row"><a class="btn" target="_blank" rel="noopener" href="https://openstax.org/books/biology-ap-courses/pages/5-1-components-and-structure">Open source image and page ↗</a></div><p class="sim-note">External content attributed to OpenStax. Their site lists its own content licence; please consult its reuse terms if republishing.</p></div>`;$$('[data-lightbox]').forEach(img=>img.onclick=()=>{const v=document.createElement('div');v.className='lightbox';v.innerHTML=`<button aria-label="Close enlarged image">✕</button><img alt="Enlarged membrane infographic" src="${img.dataset.lightbox}"/>`;document.body.appendChild(v);v.onclick=()=>v.remove()})}
function glossaryPage(){$('#resourceContent').innerHTML=`<div class="panel"><h2>Searchable membrane glossary</h2><p>${Object.keys(GLOSSARY).length} essential terms explained in exam-friendly language.</p><input id="glossarySearch" class="glossary-search" placeholder="Search term or definition…" aria-label="Search glossary"><div id="glossaryTerms"></div><div class="action-row"><button class="btn" id="printNotes">🖨 Print glossary / save as PDF</button><button class="btn danger" id="resetAll">Reset all learning progress</button></div></div>`;function show(){let term=$('#glossarySearch').value.toLowerCase();let list=Object.entries(GLOSSARY).filter(([k,v])=>k.toLowerCase().includes(term)||v.toLowerCase().includes(term));$('#glossaryTerms').innerHTML=list.map(([k,v])=>`<div class="term"><strong>${k}</strong><p>${v}</p></div>`).join('')||'<p>No matches. Try a broader term.</p>'}$('#glossarySearch').oninput=show;show();$('#printNotes').onclick=()=>window.print();$('#resetAll').onclick=()=>{if(confirm('Reset your saved lesson and activity progress?')){localStorage.removeItem('membrane-lab-v2');location.reload()}}}
function percentRow(row){const initial=+row.initial,final=+row.final;return Number.isFinite(initial)&&initial>0&&Number.isFinite(final)?(final-initial)/initial*100:null}
function practicalsPage(){const rows=state.potatoRows;$('#resourceContent').innerHTML=`<div class="panel"><div class="eyebrow">DATA SKILLS LAB</div><h2>Potato osmosis practical</h2><p>Enter observed concentrations and masses to calculate % change, then interpret a plotted graph. The starting example figures are <b>illustrative, not real experimental observations</b>. Replace them with your own measurements.</p><div class="note">Formula: <b>percentage change = (final mass − initial mass) / initial mass × 100</b>. Keep potato cylinder length, source, volume of solution, duration, temperature and blotting consistent across groups.</div><div class="table-scroll"><table class="nice-table"><thead><tr><th>Sucrose (mol dm⁻³)</th><th>Initial mass (g)</th><th>Final mass (g)</th><th>% Change</th><th>Remove</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td><input aria-label="Concentration row ${i+1}" data-row="${i}" data-col="conc" type="number" min="0" step=".05" value="${r.conc}" style="width:100px"/></td><td><input aria-label="Initial mass row ${i+1}" data-row="${i}" data-col="initial" type="number" min="0.01" step=".01" value="${r.initial}" style="width:100px"/></td><td><input aria-label="Final mass row ${i+1}" data-row="${i}" data-col="final" type="number" min="0" step=".01" value="${r.final}" style="width:100px"/></td><td id="pct${i}">${percentRow(r)?.toFixed(2)??'–'}%</td><td><button class="btn small danger" data-del="${i}" aria-label="Remove row ${i+1}">×</button></td></tr>`).join('')}</tbody></table></div><div class="action-row"><button class="btn" id="addRow">+ Add row</button><button class="btn" id="downloadCSV">Export CSV</button><button class="btn" id="resetPotato">Restore illustrative example</button></div><h3 style="margin-top:22px">Graph: % mass change versus sucrose concentration</h3><div class="sim-stage"><canvas id="potatoPlot" width="960" height="440" style="width:100%;height:auto"></canvas></div><div id="potatoInterpret" class="note"></div><h3>What should you write in your conclusion?</h3><p>Explain the overall trend in mass change as external sucrose concentration increases. A more concentrated sucrose solution generally has a lower water potential, so potato cells tend to lose more water. Estimate the isotonic concentration where percentage change reaches zero using the graph or line of best fit.</p></div><div class="panel" style="margin-top:18px"><h2>Beetroot membrane practical</h2><div class="split"><div><h3>Method checklist</h3><ol><li>Cut equal-sized beetroot discs and wash surface pigment.</li><li>Place equal volumes of water in labelled tubes or use defined solvent concentrations.</li><li>Use a controlled water bath for a fixed time.</li><li>Remove discs carefully; measure colour absorbance.</li><li>Use repeats and calculate means; graph absorbance against temperature or solvent concentration.</li></ol></div><div><h3>Validity & safety</h3><p>Keep beetroot source, disc size, water volume, pH and exposure duration controlled. Rinse thoroughly after cutting; calibrate the colorimeter and blank with distilled water. Handle heated water carefully. Ethanol is flammable: keep it away from flames and follow laboratory safety guidance.</p>${makeButton('Run beetroot simulation →','sims','small primary')}</div></div></div>`;$$('[data-col]').forEach(x=>x.oninput=e=>{let i=+e.target.dataset.row,k=e.target.dataset.col;rows[i][k]=e.target.value;persist();const v=percentRow(rows[i]);$('#pct'+i).textContent=v===null?'–':v.toFixed(2)+'%';drawPotatoPlot()});$$('[data-del]').forEach(x=>x.onclick=()=>{rows.splice(+x.dataset.del,1);persist();practicalsPage()});$('#addRow').onclick=()=>{rows.push({conc:.8,initial:3,final:3});persist();practicalsPage()};$('#resetPotato').onclick=()=>{state.potatoRows=[{conc:0,initial:3,final:3.4},{conc:.1,initial:3,final:3.2},{conc:.3,initial:3,final:3.0},{conc:.5,initial:3,final:2.7},{conc:.7,initial:3,final:2.4}];persist();practicalsPage()};$('#downloadCSV').onclick=()=>{let csv='Sucrose (mol dm^-3),Initial mass (g),Final mass (g),Percent change\n'+rows.map(r=>[r.conc,r.initial,r.final,percentRow(r)?.toFixed(3)??''].join(',')).join('\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='membrane_lab_potato_data.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};drawPotatoPlot()}
function drawPotatoPlot(){let can=$('#potatoPlot');if(!can)return;let ctx=can.getContext('2d'),W=960,H=440,points=state.potatoRows.map(r=>({x:+r.conc,y:percentRow(r)})).filter(p=>Number.isFinite(p.x)&&p.y!==null).sort((a,b)=>a.x-b.x);ctx.clearRect(0,0,W,H);ctx.fillStyle='#f7fcff';ctx.fillRect(0,0,W,H);let xMax=Math.max(.7,...points.map(p=>p.x),.1)*1.08,yMin=Math.min(-25,...points.map(p=>p.y))*1.17,yMax=Math.max(20,...points.map(p=>p.y))*1.17,xx=x=>80+x/xMax*800,yy=y=>360-(y-yMin)/(yMax-yMin)*300;ctx.strokeStyle='#dee9f2';ctx.lineWidth=2;ctx.font='16px Arial';ctx.fillStyle='#678aa0';for(let i=0;i<=5;i++){let y=yMin+i*(yMax-yMin)/5;ctx.beginPath();ctx.moveTo(75,yy(y));ctx.lineTo(910,yy(y));ctx.stroke();ctx.fillText(y.toFixed(0)+'%',20,yy(y)+5)}ctx.strokeStyle='#9caebc';ctx.beginPath();ctx.moveTo(80,60);ctx.lineTo(80,360);ctx.lineTo(910,360);ctx.stroke();ctx.strokeStyle='#ef9471';ctx.setLineDash([6,7]);ctx.beginPath();ctx.moveTo(80,yy(0));ctx.lineTo(910,yy(0));ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#60839a';for(let i=0;i<=5;i++)ctx.fillText((xMax*i/5).toFixed(2),xx(xMax*i/5)-12,387);ctx.font='bold 20px Arial';ctx.fillText('Sucrose concentration (mol dm⁻³)',340,425);ctx.save();ctx.translate(17,244);ctx.rotate(-Math.PI/2);ctx.fillText('% mass change',0,0);ctx.restore();ctx.beginPath();points.forEach((p,i)=>{if(i===0)ctx.moveTo(xx(p.x),yy(p.y));else ctx.lineTo(xx(p.x),yy(p.y))});ctx.strokeStyle='#4d95c8';ctx.lineWidth=5;ctx.stroke();points.forEach(p=>{ctx.beginPath();ctx.arc(xx(p.x),yy(p.y),8,0,2*Math.PI);ctx.fillStyle='#8d6bc5';ctx.fill();ctx.strokeStyle='#fff';ctx.lineWidth=3;ctx.stroke()});let crossing='not determined';for(let i=1;i<points.length;i++){let a=points[i-1],b=points[i];if((a.y>=0&&b.y<=0)||(a.y<=0&&b.y>=0)){let x=a.x+(0-a.y)/(b.y-a.y||1)*(b.x-a.x);crossing=x.toFixed(3)+' mol dm⁻³';break}}$('#potatoInterpret').innerHTML=`<b>Estimated zero mass-change point:</b> ${crossing}. ${points.length>=3?'This is a simple interpolation between entered points, not a formal best-fit analysis.':'Add more data points to see the trend.'} ${state.potatoRows.length} row(s) plotted; check anomalies and replicates.`}

/* Dedicated direct PDF library: PDF hrefs are exact existing documents, not a search or redirect. */
const paperView={kind:'all',query:''};
function paperLink(url,label,primary=false){return `<a class="btn ${primary?'primary':''}" target="_blank" rel="noopener noreferrer" href="${esc(url)}" aria-label="${esc(label)} (opens original external resource in a new tab)">${esc(label)} ↗</a>`}
function paperGroupFor(r){if(r.category==='Official full paper')return 'full';if(r.category==='Direct membrane question pages')return 'online';return 'topic'}
function paperCards(){
 const query=paperView.query.toLowerCase().trim();
 const data=PAST_PAPER_LINKS.filter(r=>(paperView.kind==='all'||paperGroupFor(r)===paperView.kind)&&(!query||[r.title,r.desc,r.year,r.category,r.type].join(' ').toLowerCase().includes(query)));
 const groups=[['topic','TOPIC-ONLY QUESTION PACKS','Membranes-only collections: easiest place to start.'],['online','DIRECT ONLINE MEMBRANE QUESTIONS','Open the exact question page rather than a site homepage. Some platforms may need an account.'],['full','GENUINE OCR FULL EXAM PAPERS','Official OCR question paper and mark scheme PDFs. These test several topics, not membranes alone.']];
 if(!data.length)return `<div class="panel"><h3>No papers found</h3><p>Try another year or choose All resources.</p></div>`;
 return groups.map(([kind,title,subtitle])=>{
  const items=data.filter(r=>paperGroupFor(r)===kind);
  if(!items.length)return '';
  return `<section class="paper-section"><div class="section-head"><div><div class="eyebrow">${title}</div><p class="text-muted">${subtitle}</p></div><span class="pill purple">${items.length} ${items.length===1?'resource':'resources'}</span></div><div class="paper-grid">${items.map(r=>`<article class="panel paper-card"><div class="topic-meta"><span class="pill purple">${esc(r.year)}</span><span class="pill">${esc(r.type)}</span></div><h3>${esc(r.title)}</h3><p>${esc(r.desc)}</p><div class="action-row">${paperLink(r.qp,kind==='online'?'Open exact question page':r.format==='Drive document'?'Open question file':'Open question PDF',true)}${r.ms?paperLink(r.ms,r.format==='Drive document'?'Open mark scheme file':'Open matching mark scheme'):''}</div><small class="text-muted">${esc(r.host|| (kind==='topic'?'Physics & Maths Tutor':'OCR'))} · ${esc(r.format||'PDF')} · External link</small></article>`).join('')}</div></section>`;
 }).join('')
}
function paperListMarkup(){return `<div class="note purple"><b>Real papers, clearly identified:</b> ${PAST_PAPER_LINKS.filter(x=>paperGroupFor(x)==='topic').length} curated membrane-only question packs, ${PAST_PAPER_LINKS.filter(x=>paperGroupFor(x)==='online').length} direct topic-question pages and ${PAST_PAPER_LINKS.filter(x=>paperGroupFor(x)==='full').length} official OCR full papers. Each question paper has its matching mark scheme when published separately. The 30 MCQs and 30 MSQs inside this app are <b>original OCR-style practice</b>, not verbatim past-paper questions. Some external sites or Google Drive documents may require access.</div><div class="paper-toolbar"><div class="tabbar paper-filters" role="group" aria-label="Filter past paper links">${[['all','All links'],['topic','Topic PDFs'],['online','Online questions'],['full','Official OCR papers']].map(([k,n])=>`<button type="button" data-paperfilter="${k}" class="${paperView.kind===k?'active':''}">${n}</button>`).join('')}</div><input type="search" class="glossary-search" id="paperSearch" placeholder="Search year, paper or topic…" aria-label="Search actual past papers" value="${esc(paperView.query)}"/></div><div id="paperGroups">${paperCards()}</div><div class="panel"><h3>Using genuine exam questions</h3><p>Start with topic-only packs, attempt the questions without notes, then compare with the mark scheme. For a full-paper workout use a year-specific original OCR question paper. <b>Full papers are multi-topic</b>, so choose only relevant membrane questions for topic revision.</p><div class="action-row"><a class="btn" href="https://www.ocr.org.uk/qualifications/as-and-alevel/biology-a-h020-h420-from-2015/assessment/" target="_blank" rel="noopener noreferrer">OCR official assessment archive ↗</a><a class="btn" href="#practice" onclick="state.practiceTab='bankmcq'">Practice 30 original MCQs →</a><a class="btn" href="#practice" onclick="state.practiceTab='bankmsq'">Practice 30 original MSQs →</a></div></div>`}
function pastpapersContent(selector){const c=$(selector);if(!c)return;c.innerHTML=paperListMarkup();$$('[data-paperfilter]').forEach(b=>b.onclick=()=>{paperView.kind=b.dataset.paperfilter;pastpapersContent(selector)});$('#paperSearch').oninput=e=>{paperView.query=e.target.value;$('#paperGroups').innerHTML=paperCards()}}
function pastpapers(){app.innerHTML=head('VERIFIED DIRECT LINKS','Biological Membranes · Real Past Papers','Study genuine topic-specific question sets and official OCR year-specific full papers. Each card opens the exact external PDF or question page, with matching mark schemes where available.')+`<div id="paperDirectContent"></div>`;pastpapersContent('#paperDirectContent')}
function bankPage(mode){
 const multi=mode==='msq',bank=multi?PAPER_MSQS:PAPER_MCQS,rec=state.bankAnswers[mode],i=state.bankIndex[mode]||0,q=bank[i],prev=rec[i]||{sel:[],checked:false,correct:false},sel=prev.sel||[];
 const attempted=Object.values(rec).filter(x=>x.checked).length,correct=Object.values(rec).filter(x=>x.checked&&x.correct).length;
 const nav=bank.map((_,n)=>{const s=rec[n];return `<button data-bankjump="${n}" aria-label="Go to question ${n+1}" aria-current="${n===i?'step':'false'}" class="bank-chip ${i===n?'current':''} ${s?.checked?(s.correct?'right':'missed'):''}">${n+1}</button>`}).join('');
 $('#practiceContent').innerHTML=`<div class="panel question-panel"><div class="eyebrow">OCR A BIOLOGY · 2.1.5 · ORIGINAL PAST-PAPER-STYLE</div><h2>${multi?'Multi-select questions':'Multiple-choice questions'}</h2><p>${multi?'Select <b>every</b> correct statement (there may be two or three). A point is awarded only when the whole set is correct.':'Choose the single best answer.'} These are new practice questions, <b>not copied from OCR past papers</b>. Genuine papers and mark schemes are linked below.</p><div class="bank-summary"><div><span class="bank-number">${i+1}<small> / ${bank.length}</small></span><div class="text-muted">Current question</div></div><div><span class="bank-number">${correct}<small> / ${attempted||0}</small></span><div class="text-muted">Correct / answered</div></div><div><span class="bank-number">${Math.round(attempted/bank.length*100)}%</span><div class="text-muted">Attempted</div></div></div><div class="progress-track" style="margin:20px 0"><div class="progress-fill" style="width:${attempted/bank.length*100}%"></div></div><div class="topic-meta"><span class="pill purple">${esc(q[4])}</span><span class="pill">${multi?'MSQ · choose all that apply':'MCQ · one correct answer'}</span></div><h3 class="bank-question">${esc(q[0])}</h3><div class="bank-options" role="group" aria-label="Answer choices">${q[1].map((option,n)=>{let isCorrect=multi?q[2].includes(n):q[2]===n;return `<button type="button" data-bankoption="${n}" aria-pressed="${sel.includes(n)?'true':'false'}" ${prev.checked?'disabled':''} class="bank-choice ${sel.includes(n)?'selected':''} ${prev.checked?(isCorrect?'answer-good':(sel.includes(n)?'answer-bad':'')):''}"><span class="bank-choice-letter">${'ABCD'[n]}</span><span>${esc(option)}</span><span class="bank-choice-check">${prev.checked?(isCorrect?'✓':(sel.includes(n)?'✕':'')):(sel.includes(n)?'✓':'')}</span></button>`}).join('')}</div>${prev.checked?`<div class="feedback ${prev.correct?'':'bad'}" aria-live="polite"><strong>${prev.correct?'✓ Correct — 1 mark':'Not quite — 0 marks'}</strong><p>${esc(q[3])}</p><div><strong>Correct answer${multi?'s':''}: ${multi?q[2].map(x=>'ABCD'[x]).join(', '):'ABCD'[q[2]]}</strong></div></div>`:'<div id="bankFeedback" aria-live="polite"></div>'}<div class="action-row"><button id="bankCheck" class="btn primary" ${prev.checked||!sel.length?'disabled':''}>${prev.checked?'Answer checked':'Check my answer'}</button><button id="bankRetry" class="btn" ${!prev.checked?'disabled':''}>Try again</button><button id="bankPrev" class="btn" ${i===0?'disabled':''}>← Previous</button><button id="bankNext" class="btn">${i===bank.length-1?'Back to question 1':'Next question →'}</button></div><div class="divider"></div><details class="bank-jump"><summary>Jump to any of the ${bank.length} questions</summary><div class="bank-jump-grid">${nav}</div><div class="text-muted" style="font-size:13px;margin-top:9px">Green: correct · Salmon: needs review · Blue: current question.</div></details><div class="action-row"><button class="btn small" id="bankMissed">Review my wrong answers (${Object.values(rec).filter(x=>x.checked&&!x.correct).length})</button><button class="btn small" id="bankShuffle">Random question</button><button class="btn danger small" id="bankClear">Reset this 30-question set</button></div></div><div class="note purple"><b>Genuine membrane past papers:</b> ${paperLink(multi?PAST_PAPER_LINKS[0].qp:PAST_PAPER_LINKS[1].qp,'Open real '+(multi?'topic QP':'MCQ QP'))} ${paperLink(multi?PAST_PAPER_LINKS[0].ms:PAST_PAPER_LINKS[1].ms,'Open matching MS')} <a class="btn" href="#pastpapers">More direct links →</a></div>`;
 const move=n=>{state.bankIndex[mode]=Math.max(0,Math.min(bank.length-1,n));bankPage(mode)};
 $$('[data-bankoption]').forEach(btn=>btn.onclick=()=>{
   if(prev.checked)return;
   const v=+btn.dataset.bankoption;
   if(multi){let at=sel.indexOf(v);if(at>=0)sel.splice(at,1);else sel.push(v);sel.sort((a,b)=>a-b)}else{sel.length=0;sel.push(v)}
   rec[i]={sel:[...sel],checked:false,correct:false};persist();
   $$('[data-bankoption]').forEach(b=>{const on=sel.includes(+b.dataset.bankoption);b.classList.toggle('selected',on);b.setAttribute('aria-pressed',String(on));b.querySelector('.bank-choice-check').textContent=on?'✓':''});
   $('#bankCheck').disabled=!sel.length;
 });
 $('#bankCheck').onclick=()=>{
   if(!sel.length)return;
   let actual=multi?q[2]:[q[2]];
   let right=sel.length===actual.length && sel.every(n=>actual.includes(n));
   rec[i]={sel:[...sel],checked:true,correct:right};persist();bankPage(mode);
 };
 $('#bankRetry').onclick=()=>{delete rec[i];persist();bankPage(mode)};
 $('#bankPrev').onclick=()=>move(i-1);
 $('#bankNext').onclick=()=>move((i+1)%bank.length);
 $('#bankMissed').onclick=()=>{const wrong=Object.keys(rec).filter(n=>rec[n].checked&&!rec[n].correct).map(Number);if(wrong.length)move(wrong[0]);else toast('No wrong answers recorded. Keep going!')};
 $('#bankShuffle').onclick=()=>move(Math.floor(Math.random()*bank.length));
 $('#bankClear').onclick=()=>{if(confirm(`Reset all ${bank.length} ${multi?'multi-select':'multiple-choice'} practice answers?`)){state.bankAnswers[mode]={};state.bankIndex[mode]=0;persist();bankPage(mode)}};
 $$('[data-bankjump]').forEach(b=>b.onclick=()=>move(+b.dataset.bankjump));
}

$('#menuBtn').onclick=()=>$('#nav').classList.toggle('open');
window.addEventListener('hashchange',route);window.addEventListener('visibilitychange',()=>{if(document.hidden&&state.diff.playing){/* keep state but animations throttle naturally */}});
route();
